import json
import re
from collections import OrderedDict
from lxml import etree as ET
import dict2xml


class Message(object):
    """
        Emil Message data class.


    """

    def __init__(self, emil_message_data):
        self._message = emil_message_data
        self._xml = self._convert_dict_to_xml(self._message)
        self._xml_tree = ET.ElementTree(self._xml)

    def __str__(self):
        return json.dumps(self._message, indent=4)

    def _convert_dict_to_xml(self, dict_obj):
        self._xml_string = dict2xml.dict2xml(self._sort_dict_keys(dict_obj), wrap="root", indent="  ")
        return ET.XML(self._xml_string, parser=ET.XMLParser(remove_blank_text=True))

    def _sort_dict_keys(self, obj):
        ordered_dict = OrderedDict()
        if isinstance(obj, dict):
            for k, v in sorted(obj.items()):
                ordered_dict[k] = self._sort_dict_keys(v)
            return ordered_dict
        elif isinstance(obj, list):
            return [self._sort_dict_keys(elem) for elem in obj]
        else:
            return obj

    def xpath(self, path):
        """
        Return a list of parameter values, which match an XPath expression, that specifies parameter nodes.

        :param str path: XPath expression
        :return: list of parameter values based on xpath expression
        :rtype: list(str)

        """

        return [value.text for value in self._xml_tree.xpath(path)]

    def findall(self, regex=None):
        """
        Find all values for parameter names that match a regular expression.

        :param Optional[str] regex: matched against this regex
            default is None
        :return: list of parameter values
        :rtype: list(str)

        """
        keys = self.keys(regex)
        values = []
        for key in keys:
            values.extend(self.xpath(".//{name}".format(name=key)))
        return values

    def keys(self, regex=None):
        """
        Return parameter names (optionally matching a regular expression)

        :param str regex: optional regular expression to specify a subset of parameter names
        :return: list of parameter names
        :rtype: list(str)


        """
        keys = {element.tag for element in self._xml_tree.xpath(".//*")}
        filtered_keys = sorted({key for key in keys if regex is None or re.search(regex, key)})

        return filtered_keys

    @property
    def xml(self):
        """
        Return the XML representation

        :return: XML representation
        :rtype: lxml.etree._Element
        """
        return self._xml

    @property
    def xml_string(self):
        """
        Return the dicttoxml converted XML string representation of this ResourcesUsage.

        :return: XML string representation of this ResourcesUsage
        :rtype: bytes
        """
        return ET.tostring(self._xml, pretty_print=True).decode("UTF-8")

        # return self._xml_string

    def paths(self, regex=None):
        """
        Return parameter name paths (optionally matching a regular expression)

        :param str regex: optional regular expression to specify a subset of parameter name paths
        :return: list of parameter name paths
        :rtype: list(str)

        """
        paths = [self._xml_tree.getelementpath(element) for element in self._xml_tree.iter() if len(element) == 0]

        if regex is None:
            return paths
        else:
            return [path for path in paths if re.search(regex, path)]

    def __getitem__(self, regex):
        """
        Return a parameter value for a parameter name, that matches a regular expression.


        :param str regex: regular expression, which should match exactly one parameter name
        :return: parameter value
        :rtype: str
        :raises:
            - KeyError, if no parameter name in the current resources usage matches regex
            - LookupError, if more than one parameter name matches regex
        """
        result_list = self.findall(regex)
        length = len(result_list)
        if length == 0:
            raise KeyError(regex)
        elif length > 1:
            raise LookupError(regex)
        else:
            return result_list[0]

    def __contains__(self, regex):
        """
        Check whether there is any parameter name that matches a regular expression.


        :param str regex: regular expression, which specifies parameter names, that will be checked for presence
        :return: True, if at least one parameter name matches regex
        :rtype: bool
        """
        return bool(self.findall(regex))
